const fs = require('fs');
const path = require('path');

const baseDir = '/job/data/trendshift';
const reportsDir = path.join(baseDir, 'reports');
const normDir = path.join(baseDir, 'normalized');
const homePath = '/job/tmp/trendshift-home.html';
const ghPath = '/job/tmp/trendshift-github.html';

function ensureDir(p){ fs.mkdirSync(p,{recursive:true}); }
function readIfExists(p){ try{return fs.readFileSync(p,'utf8')}catch{return null} }

function parseHome(html){
  const key='\\"initialData\\":[';
  const start=html.indexOf(key);
  if(start===-1) return [];
  const rest=html.slice(start+key.length);
  let end=rest.indexOf('}]}]]\\n"');
  if(end===-1) end=rest.indexOf('}]}]]');
  if(end===-1) return [];
  let content=rest.slice(0,end+1);
  content=content.replace(/\\u0026/g,'&').replace(/\\"/g,'"');
  try{return JSON.parse('['+content+']');}catch{return []}
}

function parseGithub(html){
  const s = html.replace(/\\u0026/g,'&').replace(/\\"/g,'"');
  const parts = s.split('rounded-lg border border-gray-300 bg-white px-4 py-3 pb-4 shadow-sm');
  const cards = [];
  for (let i=1;i<parts.length;i++){
    const chunk = parts[i].slice(0, 7000);
    const rank = Number((chunk.match(/rounded-full text-sm font-semibold","children":(\d+)/)||[])[1]);
    const fullName = (chunk.match(/"href":"\/repositories\/\d+","scroll":false,"children":"([^"]+)"/)||[])[1] || null;
    const lang = (chunk.match(/rounded-full[^\]]+\]\,"([^"]+)"\]\}\]/)||[])[1] || '';
    const nums = [...chunk.matchAll(/lucide-(?:star|git-fork)[\s\S]*?\],"([0-9.]+[kKmM]?)"\]/g)].map(m=>m[1]);
    const featured = Number((chunk.match(/Featured on GitHub Trending"," ",\["\$","span"[\s\S]*?"children":(\d+)/)||[])[1]);
    const desc = (chunk.match(/h-full text-xs leading-5 text-gray-500","children":"([\s\S]*?)"\}\]\}\]\}\]\}\]/)||[])[1] || '';
    if(rank && fullName){
      cards.push({rank, full_name:fullName, language:lang, stars:nums[0]||null, forks:nums[1]||null, featured_days: featured || null, description: desc});
    }
  }
  cards.sort((a,b)=>a.rank-b.rank);
  return cards.slice(0,25);
}

function findInterestProfile(){
  const candidates = [
    '/job/data/trendshift/interest_profile.json',
    '/job/data/interest_profile.json',
    '/job/interest_profile.json',
    '/job/data/trendshift/interest_profile.md',
    '/job/interest_profile.md'
  ];
  for(const p of candidates){ if(fs.existsSync(p)) return p; }
  return null;
}

function themeCounts(items){
  const themes = {
    'AI agents / autonomous coding': /(agent|claude|codex|openclaw|assistant|swarm)/i,
    'LLM learning + prompts': /(llm|prompt|course|learn-ai|engineering)/i,
    'Infra / sandbox / tooling': /(sandbox|framework|orchestration|tool|skills|ide)/i,
    'Content & creator automation': /(video|deepfake|moneyprinter|chat|pdf|photo)/i,
  };
  const counts = Object.fromEntries(Object.keys(themes).map(k=>[k,0]));
  for(const r of items){
    const text = `${r.full_name} ${r.repository_description||''} ${r.description||''}`;
    for(const [k,re] of Object.entries(themes)) if(re.test(text)) counts[k]++;
  }
  return counts;
}

